package com.ruoyi.web.controller.shop;
import java.util.List; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import com.ruoyi.common.annotation.Log; import com.ruoyi.common.core.controller.BaseController; import com.ruoyi.common.core.domain.AjaxResult; import com.ruoyi.common.core.page.TableDataInfo; import com.ruoyi.common.enums.BusinessType; import com.ruoyi.system.domain.shop.MallCoupon; import com.ruoyi.system.service.IMallCouponService;
@RestController @RequestMapping("/shop/coupon") public class MallCouponController extends BaseController { @Autowired private IMallCouponService service; @PreAuthorize("@ss.hasPermi('shop:coupon:list')") @GetMapping("/list") public TableDataInfo list(MallCoupon c){startPage();List<MallCoupon> list=service.selectCouponList(c);return getDataTable(list);}@PreAuthorize("@ss.hasPermi('shop:coupon:query')") @GetMapping("/{id}") public AjaxResult get(@PathVariable Long id){return success(service.selectCouponById(id));}@PreAuthorize("@ss.hasPermi('shop:coupon:add')") @Log(title="商城优惠券",businessType=BusinessType.INSERT) @PostMapping public AjaxResult add(@RequestBody MallCoupon c){c.setCreateBy(getUsername());return toAjax(service.insertCoupon(c));}@PreAuthorize("@ss.hasPermi('shop:coupon:edit')") @Log(title="商城优惠券",businessType=BusinessType.UPDATE) @PutMapping public AjaxResult edit(@RequestBody MallCoupon c){c.setUpdateBy(getUsername());return toAjax(service.updateCoupon(c));}@PreAuthorize("@ss.hasPermi('shop:coupon:status')") @PutMapping("/{id}/status") public AjaxResult status(@PathVariable Long id,@RequestBody MallCoupon c){return toAjax(service.updateStatus(id,c.getStatus(),getUsername()));}@PreAuthorize("@ss.hasPermi('shop:coupon:remove')") @Log(title="商城优惠券",businessType=BusinessType.DELETE) @DeleteMapping("/{id}") public AjaxResult remove(@PathVariable Long id){return toAjax(service.deleteCoupon(id));}}
